<script setup>
import { computed, onMounted, ref } from 'vue'
const props = defineProps({ api: { type: Function, required: true }, currentPath: { type: String, required: true }, onSecurePath: { type: Function, required: true } })
const groups = ref({}), selected = ref('site'), draft = ref({}), loading = ref(false), saving = ref(false), error = ref(''), notice = ref(''), extra = ref({ emailTemplates: [], themeTemplates: [], telegram: null })
const labels = { invite:'邀请与返利',site:'站点',subscribe:'订阅',frontend:'前台外观',server:'节点服务',email:'邮件服务',telegram:'Telegram',app:'客户端',safe:'安全',subscribe_template:'订阅模板' }
const fieldLabels = { invite_force:'强制使用邀请码',invite_commission:'默认返佣比例（%）',invite_gen_limit:'每用户可生成邀请码数',invite_never_expire:'邀请码永不过期',commission_first_time_enable:'首单返佣',commission_auto_check_enable:'自动审核返佣',commission_withdraw_limit:'最低提现金额',commission_withdraw_method:'提现方式白名单',withdraw_close_enable:'关闭提现功能',commission_distribution_enable:'多级分销',commission_distribution_l1:'一级返佣比例（%）',commission_distribution_l2:'二级返佣比例（%）',commission_distribution_l3:'三级返佣比例（%）',logo:'站点 Logo 地址',force_https:'强制 HTTPS',stop_register:'关闭用户注册',app_name:'站点名称',app_description:'站点描述',app_url:'站点 URL',subscribe_url:'订阅链接域名',try_out_plan_id:'试用套餐 ID',try_out_hour:'试用时长（小时）',tos_url:'服务条款 URL',currency:'货币代码',currency_symbol:'货币符号',ticket_must_wait_reply:'用户需等待管理员回复',plan_change_enable:'允许变更套餐',reset_traffic_method:'流量重置方式',surplus_enable:'启用剩余价值折抵',new_order_event_id:'新购通知事件',renew_order_event_id:'续费通知事件',change_order_event_id:'变更套餐通知事件',show_info_to_server_enable:'向节点下发用户信息',show_protocol_to_server_enable:'向节点下发协议',default_remind_expire:'默认发送到期提醒',default_remind_traffic:'默认发送流量提醒',subscribe_path:'订阅路径',frontend_theme:'当前前台主题',frontend_theme_sidebar:'侧边栏主题',frontend_theme_header:'页头主题',frontend_theme_color:'主题配色',frontend_background_url:'前台背景图 URL',server_token:'节点通讯令牌',server_pull_interval:'节点拉取间隔（秒）',server_push_interval:'节点上报间隔（秒）',device_limit_mode:'设备限制模式',server_ws_enable:'启用节点 WebSocket',server_ws_url:'节点 WebSocket URL',email_host:'SMTP 服务器',email_port:'SMTP 端口',email_username:'SMTP 用户名',email_password:'SMTP 密码',email_encryption:'邮件加密方式',email_from_address:'发件人地址',remind_mail_enable:'启用邮件提醒',telegram_bot_enable:'启用 Telegram Bot',telegram_bot_token:'Telegram Bot Token',telegram_webhook_url:'Telegram Webhook URL',telegram_discuss_link:'讨论群链接',telegram_discuss_id:'讨论群 ID',telegram_channel_id:'频道 ID',windows_version:'Windows 客户端版本',windows_download_url:'Windows 下载地址',macos_version:'macOS 客户端版本',macos_download_url:'macOS 下载地址',android_version:'Android 客户端版本',android_download_url:'Android 下载地址',email_verify:'启用邮箱验证',safe_mode_enable:'安全模式',secure_path:'管理员安全路径',email_whitelist_enable:'启用邮箱后缀白名单',email_whitelist_suffix:'允许的邮箱后缀',email_gmail_limit_enable:'限制 Gmail 注册',captcha_enable:'启用人机验证',captcha_type:'人机验证类型',recaptcha_key:'reCAPTCHA 密钥',recaptcha_site_key:'reCAPTCHA Site Key',recaptcha_v3_secret_key:'reCAPTCHA v3 密钥',recaptcha_v3_site_key:'reCAPTCHA v3 Site Key',recaptcha_v3_score_threshold:'reCAPTCHA v3 分数阈值',turnstile_secret_key:'Cloudflare Turnstile 密钥',turnstile_site_key:'Cloudflare Turnstile Site Key',register_limit_by_ip_enable:'按 IP 限制注册频率',register_limit_count:'IP 注册次数上限',register_limit_expire:'注册限制周期（分钟）',password_limit_enable:'启用密码错误限制',password_limit_count:'密码错误次数上限',password_limit_expire:'密码限制周期（分钟）',recaptcha_enable:'启用 reCAPTCHA（兼容项）',subscribe_template_singbox:'Sing-box 订阅模板',subscribe_template_clash:'Clash 订阅模板',subscribe_template_clashmeta:'Clash Meta 订阅模板',subscribe_template_stash:'Stash 订阅模板',subscribe_template_surge:'Surge 订阅模板',subscribe_template_surfboard:'Surfboard 订阅模板' }
const fieldLabel = key => fieldLabels[key] || key.replaceAll('_',' ')
const keys = computed(() => Object.keys(draft.value || {}))
function parseValue(key, value) { const original=groups.value[selected.value]?.[key]; if(original!==null&&typeof original==='object'){try{return JSON.parse(value)}catch{throw new Error(`${key} 需要有效 JSON`)}} if(typeof original==='boolean')return Boolean(value); if(typeof original==='number')return value===''?null:Number(value); return value }
async function load() { loading.value=true; error.value=''; try { groups.value=await props.api('config/fetch'); draft.value={...(groups.value[selected.value]||{})}; const [emailTemplates,themeTemplates]=await Promise.all([props.api('config/getEmailTemplate'),props.api('config/getThemeTemplate')]); extra.value.emailTemplates=emailTemplates; extra.value.themeTemplates=themeTemplates } catch(e){error.value=e.message} finally{loading.value=false} }
function choose(group){selected.value=group;draft.value={...(groups.value[group]||{})};notice.value=''}
async function save(){saving.value=true;error.value='';notice.value='';try{const payload={};for(const key of keys.value)payload[key]=parseValue(key,draft.value[key]);const newPath=payload.secure_path;if(newPath&&newPath!==props.currentPath&&!/^[a-zA-Z0-9_-]{8,}$/.test(newPath))throw new Error('管理员安全路径至少 8 位，且只能包含字母、数字、下划线和中划线。');if(newPath&&newPath!==props.currentPath&&!window.confirm('保存安全路径会立即改变管理员 API 地址。继续后将使用新路径继续请求。'))return;await props.api('config/save',{method:'POST',body:payload});groups.value[selected.value]={...payload};if(newPath&&newPath!==props.currentPath)props.onSecurePath(newPath);notice.value='配置已保存。'}catch(e){error.value=e.message}finally{saving.value=false}}
async function testMail(){try{await props.api('config/testSendMail',{method:'POST',body:{}});notice.value='测试邮件已提交至当前管理员邮箱。'}catch(e){error.value=e.message}}
async function setWebhook(){if(!window.confirm('根据当前 Telegram Bot 配置设置 Webhook？'))return;try{extra.value.telegram=await props.api('config/setTelegramWebhook',{method:'POST',body:{telegram_bot_token:draft.value.telegram_bot_token}});notice.value='Telegram Webhook 已设置。'}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section class="config-view"><div class="page-title-row"><div><p class="eyebrow">SYSTEM / CONFIGURATION</p><h1>站点配置<span class="title-period">.</span></h1><p class="page-subtitle">读取并保存 Xboard 配置分组；安全路径变更会同步更新当前连接。</p></div><button class="refresh-button" @click="load">↻ <span>重新读取</span></button></div><div class="config-layout"><nav class="config-groups"><button v-for="(value,key) in groups" :key="key" :class="{selected:selected===key}" @click="choose(key)">{{labels[key]||key}}</button></nav><div class="data-panel config-editor"><div class="panel-heading"><div><p class="eyebrow">{{selected.toUpperCase()}} / SETTINGS</p><h2>{{labels[selected]||selected}}</h2></div><span v-if="loading" class="status-label">读取中…</span></div><div v-if="loading" class="table-state">正在读取配置…</div><div v-else class="config-fields"><label v-for="key in keys" :key="key" class="config-field"><span>{{fieldLabel(key)}}<small>{{key}}</small></span><input v-if="typeof groups[selected]?.[key]==='boolean'" v-model="draft[key]" type="checkbox"><input v-else-if="typeof groups[selected]?.[key]==='number'" v-model="draft[key]" type="number" step="any"><textarea v-else-if="groups[selected]?.[key]!==null && typeof groups[selected]?.[key]==='object' || String(draft[key]??'').length>240" v-model="draft[key]" rows="5" spellcheck="false"></textarea><input v-else v-model="draft[key]" :type="/(password|token|secret|key)/i.test(key)?'password':'text'"></label></div><p v-if="error" class="notice">{{error}}</p><p v-if="notice" class="notice success">{{notice}}</p><div class="config-actions"><button v-if="selected==='email'" @click="testMail">向管理员邮箱发送测试邮件</button><button v-if="selected==='telegram'" @click="setWebhook">设置 Telegram Webhook</button><button class="save-button" :disabled="saving||loading" @click="save">{{saving?'保存中…':'保存此分组'}}</button></div><pre v-if="extra.telegram" class="response-json">{{JSON.stringify(extra.telegram,null,2)}}</pre></div></div><div class="config-meta"><article class="data-panel"><p class="eyebrow">AVAILABLE TEMPLATES</p><h2>邮件模板文件</h2><code>{{extra.emailTemplates.join(' · ')||'—'}}</code></article><article class="data-panel"><p class="eyebrow">THEME ASSETS</p><h2>前台主题目录</h2><code>{{extra.themeTemplates.join(' · ')||'—'}}</code></article></div></section></template>
